template:
use std::sync::mpsc::{channel, Receiver};
use std::sync::{Arc, Mutex};
use std::thread;

fn receive_two(rx: Receiver<i32>) -> i32 {
    let rx = ⟦slot1⟧;
    let mut handles = Vec::new();
    for _ in 0..2 {
        let rx_ref = ⟦slot2⟧;
        handles.push(thread::spawn(move || {
            rx_ref.lock().unwrap().recv().unwrap_or(0)
        }));
    }
    let mut sum = 0;
    for h in handles { sum += h.join().unwrap(); }
    sum
}

tests:
#[test]
fn reads_both() {
    let (tx, rx) = channel();
    tx.send(10).unwrap();
    tx.send(20).unwrap();
    assert_eq!(receive_two(rx), 30);
}
